
(() => {
  'use strict';
  const $=(id)=>document.getElementById(id);
  const hub=$('hub-view'), view=$('practice1-view');
  const BASE={pizza:30,labor:100,ex:0.50,ey:0.60};
  const fmt2=new Intl.NumberFormat('ca-ES',{minimumFractionDigits:2,maximumFractionDigits:2});
  const ppcPdfBase64="";

  function parseNum(v){
    let s=String(v??'').trim().replace(/\s/g,'');
    if(!s) return NaN;
    const c=s.lastIndexOf(','), d=s.lastIndexOf('.');
    if(c>=0&&d>=0){const k=Math.max(c,d);s=s.slice(0,k).replace(/[.,]/g,'')+'.'+s.slice(k+1);}
    else if(c>=0) s=s.replace(',','.');
    return Number(s);
  }
  const r2=(v)=>Number.isFinite(v)?Number(v.toFixed(2)):NaN;
  function seedFromId(id){const s=String(id??'').trim();const last=s.slice(-4);return /^\d+$/.test(last)?Number(last):6380;}
  function pars(seed){
    const u1=((seed*37+11)%997)/996;
    const u2=((seed*53+29)%991)/990;
    return {A:8.8+0.4*u1,B:4.9+0.2*u2};
  }
  function yFrontier(x,labor,ex,ey,p){
    if(!(Number.isFinite(x)&&Number.isFinite(labor)&&Number.isFinite(ex)&&Number.isFinite(ey))||labor<=0||ex<=0||ey<=0||x<0) return NaN;
    const lx=Math.pow(x/p.B,1/ex);
    const rem=labor-lx;
    if(rem<0) return NaN;
    return p.A*Math.pow(Math.max(0,rem),ey);
  }
  function xEnd(labor,ex,p){return p.B*Math.pow(Math.max(0,labor),ex);}
  function yEnd(labor,ey,p){return p.A*Math.pow(Math.max(0,labor),ey);}
  function visibleY(x,p,labor=100,ex=.5,ey=.6){return r2(yFrontier(x,labor,ex,ey,p));}
  function visibleOC(x,p){return r2(visibleY(x,p)-visibleY(x+1,p));}
  function targetLabor(x,target,p,ex=.5,ey=.6){return Math.pow(x/p.B,1/ex)+Math.pow(target/p.A,1/ey);}

  const qdefs=[
    {reset:true,q:'Fixa la producció de pizza en 30. Quina és la quantitat màxima de pasta que es pot produir?',unit:'pasta',kind:'exactY',x:30},
    {reset:true,q:'Fixa la producció de pizza en 35. Escriu una quantitat de pasta que sigui assolible però ineficient.',unit:'pasta',kind:'inefficient',x:35},
    {q:'En aquest mateix cas, quina quantitat de pasta és assolible i eficient?',unit:'pasta',kind:'exactY',x:35},
    {q:'En aquest mateix cas, escriu una quantitat de pasta que sigui inassolible.',unit:'pasta',kind:'unattainable',x:35},
    {reset:true,q:'Fixa la producció de pizza en 20. Escriu una quantitat de pasta que sigui assolible però ineficient.',unit:'pasta',kind:'inefficient',x:20},
    {q:'En aquest mateix cas, quina quantitat de pasta és assolible i eficient?',unit:'pasta',kind:'exactY',x:20},
    {q:'En aquest mateix cas, escriu una quantitat de pasta que sigui inassolible.',unit:'pasta',kind:'unattainable',x:20},
    {reset:true,q:'Fixa la producció de pizza en 30. Són 100 unitats de pasta assolibles o inassolibles?',unit:'',kind:'classify',x:30,y:100,options:['Assolible','Inassolible']},
    {q:'En aquest mateix cas, són 115 unitats de pasta assolibles o inassolibles?',unit:'',kind:'classify',x:30,y:115,options:['Assolible','Inassolible']},
    {reset:true,q:'Fixa la producció de pizza en 40. Escriu una quantitat de pasta que sigui inassolible.',unit:'pasta',kind:'unattainable',x:40},
    {reset:true,q:'Fixa la producció de pizza en 35. Quin treball total cal perquè la producció màxima de pasta sigui 105?',unit:'treball',kind:'laborTarget',x:35,target:105},
    {reset:true,q:"Fixa la producció de pizza en 35. Quin és el cost d'oportunitat, en pasta, de produir una pizza més?",unit:'pasta',kind:'oc',x:35},
    {reset:true,q:"Quin és el cost d'oportunitat marginal d'una pizza quan la producció de pizza és 10?",unit:'pasta',kind:'oc',x:10},
    {q:"Mantenint la resta de valors inicials, quin és el cost d'oportunitat marginal d'una pizza quan la producció de pizza és 30?",unit:'pasta',kind:'oc',x:30},
    {q:"Mantenint la resta de valors inicials, quin és el cost d'oportunitat marginal d'una pizza quan la producció de pizza és 40?",unit:'pasta',kind:'oc',x:40},
    {q:"A partir de les preguntes 13-15, quan augmenta la producció de pizza, el cost de produir una pizza addicional augmenta o disminueix?",unit:'',kind:'trend',options:['Augmenta','Disminueix','No canvia']},
    {reset:true,q:'Fixa la producció de pizza en 40. Quin treball total cal perquè la producció màxima de pasta sigui 140?',unit:'treball',kind:'laborTarget',x:40,target:140}
  ];

  function renderQuestions(){
    const host=$('ppc-questions-body'); host.innerHTML='';
    qdefs.forEach((d,i)=>{
      const row=document.createElement('div');row.className='q-row';
      const n=document.createElement('div');n.className='q-num';n.textContent=String(i+1);
      const t=document.createElement('div');t.className='q-text';
      if(d.reset){const b=document.createElement('strong');b.textContent='Torna als valors inicials. ';t.appendChild(b);}
      t.appendChild(document.createTextNode(d.q));
      if(i===10){
        const sb=document.createElement('button');
        sb.type='button';sb.className='fpp-solver-link';sb.textContent='Solver';
        sb.addEventListener('click',openQuestion11Solver);
        t.appendChild(sb);
      }
      const a=document.createElement('div');a.className='q-answer';
      let c;
      if(d.options){c=document.createElement('select');const p=document.createElement('option');p.value='';p.textContent='Selecciona';c.appendChild(p);d.options.forEach(o=>{const op=document.createElement('option');op.value=o;op.textContent=o;c.appendChild(op);});}
      else{c=document.createElement('input');c.type='text';c.inputMode='decimal';c.autocomplete='off';}
      c.id=`ppc-answer-${i+1}`;c.addEventListener('input',()=>check(i));c.addEventListener('change',()=>check(i));a.appendChild(c);
      const u=document.createElement('div');u.className='q-unit';u.textContent=d.unit;
      const k=document.createElement('div');k.className='q-check blank';k.id=`ppc-check-${i+1}`;k.textContent='·';
      row.append(n,t,a,u,k);host.appendChild(row);
    });
  }

  function openQuestion11Solver(){
    const modal=$('fpp-solver-modal');
    if(!modal)return;
    $('fpp-solver-target').value='105';
    $('fpp-solver-result').className='fpp-solver-result';
    $('fpp-solver-result').textContent='Prem «Resoldre» per trobar el valor de treball que fa que la pasta màxima sigui 105.';
    modal.classList.add('show');modal.setAttribute('aria-hidden','false');
  }
  function closeQuestion11Solver(){
    const modal=$('fpp-solver-modal');if(!modal)return;
    modal.classList.remove('show');modal.setAttribute('aria-hidden','true');
  }
  function runQuestion11Solver(){
    const p=pars(seedFromId(($('ppc-student-id').dataset.studentId || $('ppc-student-id').value)));
    const target=parseNum($('fpp-solver-target').value);
    const mode=document.querySelector('input[name="fpp-solver-mode"]:checked')?.value||'value';
    if(mode!=='value'||!Number.isFinite(target)){ $('fpp-solver-result').textContent='Per aquesta pregunta utilitza «Valor de» i introdueix un valor numèric.';return; }
    const labor=targetLabor(35,target,p,.5,.6);
    const shown=r2(yFrontier(35,labor,.5,.6,p));
    $('fpp-solver-result').className='fpp-solver-result ok';
    $('fpp-solver-result').innerHTML='<strong>Solució</strong><br>Treball disponible ≈ '+fmt2.format(labor)+' · Producció màxima de pasta = '+fmt2.format(shown);
    $('ppc-labor').value=fmt2.format(labor);$('ppc-pizza').value='35,00';update();
  }

  function check(i){
    const d=qdefs[i], c=$(`ppc-answer-${i+1}`), box=$(`ppc-check-${i+1}`);if(!c||!box)return;
    const raw=c.value;if(raw===''){box.className='q-check blank';box.textContent='·';return;}
    const p=pars(seedFromId(($('ppc-student-id').dataset.studentId || $('ppc-student-id').value)));
    let ok=false;
    if(d.kind==='classify'){const max=visibleY(d.x,p);const expected=d.y<=max?'Assolible':'Inassolible';ok=raw===expected;}
    else if(d.kind==='trend') ok=raw==='Augmenta';
    else{
      const v=parseNum(raw);if(Number.isFinite(v)){const vv=r2(v);const max=visibleY(d.x,p);
        if(d.kind==='exactY') ok=vv===max;
        else if(d.kind==='inefficient') ok=vv>=0 && vv<max;
        else if(d.kind==='unattainable') ok=vv>max;
        else if(d.kind==='oc') ok=vv===visibleOC(d.x,p);
        else if(d.kind==='laborTarget'){const shown=r2(yFrontier(d.x,v,.5,.6,p));ok=shown===r2(d.target);}
      }
    }
    box.className='q-check '+(ok?'correct':'wrong');box.textContent=ok?'Correcte':'Revisa-ho';
  }

  function readModel(){
    return {pizza:parseNum($('ppc-pizza').value),labor:parseNum($('ppc-labor').value),ex:parseNum($('ppc-ex').value),ey:parseNum($('ppc-ey').value)};
  }
  function resetModel(){
    $('ppc-pizza').value='30,00';$('ppc-labor').value='100,00';$('ppc-ex').value='0,50';$('ppc-ey').value='0,60';update();
  }
  function svgEl(name,attrs={}){const el=document.createElementNS('http://www.w3.org/2000/svg',name);Object.entries(attrs).forEach(([k,v])=>el.setAttribute(k,String(v)));return el;}
  function draw(m,p){
    const svg=$('ppc-chart');while(svg.firstChild)svg.removeChild(svg.firstChild);
    const box=svg.getBoundingClientRect();const W=Math.max(520,Math.round(box.width||650)),H=Math.max(500,Math.round(box.height||650));svg.setAttribute('viewBox',`0 0 ${W} ${H}`);
    const margin={l:62,r:20,t:18,b:54},pw=W-margin.l-margin.r,ph=H-margin.t-margin.b;
    const xe=xEnd(m.labor,m.ex,p),ye=yEnd(m.labor,m.ey,p);
    if(!(Number.isFinite(xe)&&Number.isFinite(ye)&&xe>0&&ye>0))return;
    const xMax=Math.ceil(xe/5)*5,yMax=Math.ceil(ye/10)*10;
    const X=(v)=>margin.l+(v/xMax)*pw,Y=(v)=>margin.t+ph-(v/yMax)*ph;
    const grid=svgEl('g');
    for(let i=0;i<=6;i++){const val=yMax*i/6,yy=Y(val);grid.appendChild(svgEl('line',{x1:margin.l,y1:yy,x2:W-margin.r,y2:yy,stroke:'#d6d4cf','stroke-width':1,'stroke-dasharray':'2 3'}));const t=svgEl('text',{x:margin.l-8,y:yy+3.5,'text-anchor':'end','font-size':10,fill:'#555b5e'});t.textContent=fmt2.format(val).replace(',00','');grid.appendChild(t);}
    for(let i=0;i<=6;i++){const val=xMax*i/6,xx=X(val);const t=svgEl('text',{x:xx,y:H-margin.b+18,'text-anchor':'middle','font-size':10,fill:'#555b5e'});t.textContent=fmt2.format(val).replace(',00','');grid.appendChild(t);}
    svg.appendChild(grid);
    svg.appendChild(svgEl('line',{x1:margin.l,y1:margin.t,x2:margin.l,y2:H-margin.b,stroke:'#4e5356','stroke-width':1.2}));svg.appendChild(svgEl('line',{x1:margin.l,y1:H-margin.b,x2:W-margin.r,y2:H-margin.b,stroke:'#4e5356','stroke-width':1.2}));
    let path='',area=`M ${X(0)} ${Y(0)} L ${X(0)} ${Y(ye)}`;
    const N=180;for(let i=0;i<=N;i++){const xx=xe*i/N,yy=yFrontier(xx,m.labor,m.ex,m.ey,p);if(Number.isFinite(yy)){const seg=`${i?'L':'M'} ${X(xx)} ${Y(yy)}`;path+=seg+' ';area+=` L ${X(xx)} ${Y(yy)}`;}}
    area+=` L ${X(xe)} ${Y(0)} Z`;
    svg.appendChild(svgEl('path',{d:area,fill:'#eef2f2',stroke:'none'}));
    svg.appendChild(svgEl('path',{d:path,fill:'none',stroke:'#1f6d95','stroke-width':3,'stroke-linecap':'round'}));
    const cy=yFrontier(m.pizza,m.labor,m.ex,m.ey,p);
    if(Number.isFinite(cy)&&m.pizza>=0&&m.pizza<=xe){svg.appendChild(svgEl('line',{x1:X(m.pizza),y1:Y(0),x2:X(m.pizza),y2:Y(cy),stroke:'#aaa49b','stroke-width':1.2,'stroke-dasharray':'5 5'}));svg.appendChild(svgEl('line',{x1:X(0),y1:Y(cy),x2:X(m.pizza),y2:Y(cy),stroke:'#aaa49b','stroke-width':1.2,'stroke-dasharray':'5 5'}));svg.appendChild(svgEl('circle',{cx:X(m.pizza),cy:Y(cy),r:5,fill:'#e8682b',stroke:'#fff','stroke-width':1.5}));}
    const xt=svgEl('text',{x:margin.l+pw/2,y:H-8,'text-anchor':'middle','font-size':11.5,fill:'#353a3d','font-weight':700});xt.textContent='Pizza';svg.appendChild(xt);
    const yt=svgEl('text',{x:16,y:margin.t+ph/2,'text-anchor':'middle','font-size':11.5,fill:'#353a3d','font-weight':700,transform:`rotate(-90 16 ${margin.t+ph/2})`});yt.textContent='Pasta';svg.appendChild(yt);
  }
  function update(){
    const p=pars(seedFromId(($('ppc-student-id').dataset.studentId || $('ppc-student-id').value))),m=readModel();
    const y=yFrontier(m.pizza,m.labor,m.ex,m.ey,p),xe=xEnd(m.labor,m.ex,p),ye=yEnd(m.labor,m.ey,p),oc=(Number.isFinite(y)&&Number.isFinite(yFrontier(m.pizza+1,m.labor,m.ex,m.ey,p)))?r2(y-yFrontier(m.pizza+1,m.labor,m.ex,m.ey,p)):NaN;
draw(m,p);qdefs.forEach((_,i)=>{const c=$(`ppc-answer-${i+1}`);if(c&&c.value!=='')check(i);});
  }
  function openPdf(){try{const raw=atob(ppcPdfBase64),bytes=new Uint8Array(raw.length);for(let i=0;i<raw.length;i++)bytes[i]=raw.charCodeAt(i);const url=URL.createObjectURL(new Blob([bytes],{type:'application/pdf'}));const w=window.open(url,'_blank','noopener');if(!w){const a=document.createElement('a');a.href=url;a.target='_blank';a.rel='noopener';a.click();}setTimeout(()=>URL.revokeObjectURL(url),60000);}catch(e){alert('No s’ha pogut obrir el PDF.');console.error(e);}}

  
  $('ppc-reset-model').addEventListener('click',resetModel);
  $('ppc-student-id').addEventListener('input',()=>{resetModel();qdefs.forEach((_,i)=>{const c=$(`ppc-answer-${i+1}`);if(c&&c.value!=='')check(i);});});
  ['ppc-pizza','ppc-labor','ppc-ex','ppc-ey'].forEach(id=>$(id).addEventListener('input',update));
  window.addEventListener('resize',update);
  $('fpp-solver-close')?.addEventListener('click',closeQuestion11Solver);
  $('fpp-solver-cancel')?.addEventListener('click',closeQuestion11Solver);
  $('fpp-solver-run')?.addEventListener('click',runQuestion11Solver);
  $('fpp-solver-modal')?.addEventListener('click',e=>{if(e.target===$('fpp-solver-modal'))closeQuestion11Solver()});
  renderQuestions();resetModel();requestAnimationFrame(update);

})();
